var e={"01-hello":JSON.parse(`{"bigPicture":"يثبت هذا البرنامج الأول أن اللوحة حيّة. تعمل <code>setup()</code> مرة واحدة: تفتح المراقب التسلسلي وتطبع بطاقة هوية الشريحة. ثم تعمل <code>loop()</code> إلى الأبد، فتدفع LED الـ RGB المدمج خطوة واحدة حول عجلة الألوان في كل مرة، فترى قوس قزح بطيئًا.","files":{"labs/01-hello/src/main.cpp":{"stops":{"0":{"title":"ماذا يفعل هذا البرنامج","say":"الأسطر التي تبدأ بـ <code>//</code> تعليقات: ملاحظات للبشر يتجاهلها المترجم. يخبرك هذا التعليق بالخطة: اطبع بطاقة هوية، ثم أدر LED عبر الألوان. ويسمّي أيضًا الدالتين اللتين في كل برنامج Arduino: تعمل <code>setup()</code> مرة واحدة، وتعمل <code>loop()</code> مرارًا وتكرارًا.","deep":"في الخلفية يملك نواة Arduino دالة <code>main()</code> خاصة بها: تبدأ FreeRTOS، وتنشئ مهمة تستدعي <code>setup()</code> مرة واحدة ثم تستدعي <code>loop()</code> داخل حلقة <code>for</code> لا تنتهي."},"1":{"title":"استعر صندوق الأدوات","say":"يلصق <code>#include</code> ملفًا آخر قبل الترجمة. يجلب <code>Arduino.h</code> أدوات جاهزة مثل <code>Serial</code> و<code>delay()</code> و<code>millis()</code>. أما <code>pins.h</code> فهو ملفنا الذي يقول أي سلك يذهب إلى أين.","deep":"تبحث الأقواس الزاوية في مجلدات المكتبات والإطار؛ وتبحث علامات الاقتباس في المشروع أولًا. يُعثر على <code>pins.h</code> عبر خيار البناء <code>-Iinclude</code> في <code>platformio.ini</code>."},"2":{"title":"رقمان يمكنك تعديلهما","say":"الأرقام المسمّاة تجعل الشيفرة أسهل قراءةً وتعديلًا. يخفّت <code>kBrightness</code> الـ LED شديد السطوع إلى نحو سدس قدرته؛ ويحدد <code>kHeartbeatMs</code> كم مرة (5000 ms = 5 ثوانٍ) تطبع اللوحة سطر “ما زلت حيّة”.","deep":"تعني <code>constexpr</code> أن القيمة ثابتة وقت الترجمة، فلا تكلّف ذاكرة وقت التشغيل. ويبقي <code>namespace { ... }</code> غير المسمّى هذه الأسماء خاصة بهذا الملف. يحمل <code>uint8_t</code> من 0 إلى 255؛ ويحمل <code>uint32_t</code> حتى نحو 4 مليارات."},"3":{"title":"وصفة عجلة الألوان","say":"أعطها موضعًا من 0 إلى 255 فتعيد لك مقدارًا من الأحمر والأخضر والأزرق. للعجلة ثلاث شرائح: يتحول الأحمر تدريجيًا إلى أخضر، والأخضر إلى أزرق، والأزرق عائدًا إلى أحمر. زِد الموضع خطوة خطوة تحصل على قوس قزح سلس.","deep":"عرض كل شريحة 85 خطوة، و<code>pos * 3</code> يمدّ 0-84 إلى 0-252. تعني <code>&amp;</code> في <code>uint8_t &amp;r</code> أن الدالة تكتب مباشرة في متغيرات المستدعي بدل إعادة قيمة واحدة."},"4":{"title":"اطبع بطاقة هوية الشريحة","say":"يكتب كل سطر <code>Serial.printf</code> صفًا من البطاقة التي تراها في المراقب التسلسلي: طراز الشريحة وحجم flash وحجم PSRAM والذاكرة الحرة. تخبرك الملاحظات بين الأقواس بما يُتوقع على N16R8: ‏16 MB من flash ونحو 8 MB من PSRAM.","deep":"يملأ <code>printf</code> كل <code>%s</code> أو <code>%d</code> أو <code>%lu</code> بالقيمة التالية. تعود الأحجام بالبايت، فالقسمة على <code>1024 * 1024</code> تحوّلها إلى ميغابايت. الـ heap هي الذاكرة المتبقية ليستعيرها البرنامج أثناء عمله."},"5":{"title":"العنوان الفريد للوحة","say":"تغادر كل شريحة المصنع بعنوان MAC خاص بها، وهو المعرّف الذي ستستخدمه على Wi-Fi وBluetooth. تطبع هذه الحلقة بايتاته الستة كأزواج من الحروف والأرقام تفصل بينها نقطتان، ثم إصدار حزمة البرمجيات بداخلها.","deep":"يعيش MAC ذو 48 بتًا في eFuses، وهي بتات تُبرمج مرة واحدة داخل الشريحة. يزلق <code>(mac >> (8 * i)) &amp; 0xFF</code> البايت <code>i</code> إلى الأسفل ويبقي عليه وحده؛ ويطبعه <code>%02X</code> كرقمين سداسيين عشريين بحروف كبيرة."},"6":{"title":"اصرخ إن كانت اللوحة خاطئة","say":"إذا أبلغت الشريحة بعدم وجود PSRAM، أو بذاكرة flash أقل مما دفعنا ثمنه، تطبع خطأ أحمر أو تحذيرًا أصفر. الصمت هنا يعني أن العتاد يطابق الملصق.","deep":"<code>log_e</code> و<code>log_w</code> ماكروهات التسجيل في نواة ESP32. يُبقي <code>CORE_DEBUG_LEVEL=3</code> في <code>platformio.ini</code> الأخطاء والتحذيرات وأسطر المعلومات؛ ويلوّنها مرشّح <code>colorize</code> في المراقب بحسب المستوى."},"7":{"title":"أيقظ المراقب التسلسلي","say":"يعمل هذا مرة واحدة، بعد التشغيل أو إعادة الضبط مباشرة. يفتح الاتصال التسلسلي بسرعة 115200 بت في الثانية، وينتظر لحظة، ويطبع بطاقة الهوية، ثم يخبرك بأي طرف يوجد LED الـ RGB.","deep":"على منفذ COM تنقل شريحة USB-إلى-تسلسلي منفذ UART0 في ESP32 إلى حاسوبك؛ ويجب أن يتفق الطرفان على السرعة، ولهذا فإن <code>monitor_speed</code> هو 115200 أيضًا. تضيف <code>log_i</code> المستوى والملف والسطر إلى كل رسالة.","quiz":{"question":"ما الأرجح أن يحدث لو حذفت <code>delay(1500)</code>؟","options":["سترفض اللوحة البدء","قد يفوتك أعلى بطاقة الهوية","سيجري قوس قزح أسرع"],"why":"تُطبع البطاقة فورًا، قبل أن ينتهي المراقب على حاسوبك من إعادة الاتصال بعد إعادة الضبط، فقد تمرّ الأسطر الأولى دون أن تراها. تمنحه الوقفة وقتًا للاستماع."}},"8":{"title":"خطوة واحدة حول قوس قزح","say":"في كل دورة تختار اللون عند الموضع <code>hue</code>، وتحرّك <code>hue</code> خطوة، وتخفّت اللون بـ <code>kBrightness</code> وترسله إلى LED. آلاف الخطوات الصغيرة تصنع قوس القزح السلس الذي تراه.","deep":"تحتفظ المتغيرات <code>static</code> بقيمتها بين استدعاءات <code>loop()</code> بدل أن تبدأ من جديد. تقود <code>rgbLedWrite</code> عنّا بروتوكول التوقيت أحادي السلك لـ LED من نوع WS2812، باستخدام طرفية RMT في S3. يقلّص <code>r * kBrightness / 255</code> المدى 0-255 إلى 0-40.","quiz":{"question":"<code>hue</code> من النوع <code>uint8_t</code> (من 0 إلى 255). ماذا يحدث بعد أن يصل إلى 255؟","options":["ينهار البرنامج","يعود إلى 0 ويتكرر قوس قزح","يبقى عند 255 ويتوقف LED عن التغيّر"],"why":"لا يتسع عدد غير موقّع من 8 بتات للرقم 256، فيعود إلى 0، مثل عدّاد الرحلة في السيارة. وهذا ما نريده بالضبط: تبدأ عجلة الألوان دورتها التالية."}},"9":{"title":"نبضة قلب كل خمس ثوانٍ","say":"<code>millis()</code> ساعة إيقاف بدأت عند التشغيل. عندما تمر خمس ثوانٍ منذ آخر نبضة، تطبع اللوحة المدة التي ظلت فيها حيّة وقيمة hue الحالية، ثم تعيد ضبط علامتها. لا يتوقف قوس قزح أثناء الانتظار.","deep":"الطرح أولًا (<code>millis() - lastHeartbeat</code>) يُبقي الاختبار صحيحًا حتى عندما يلتف العدّاد ذو 32 بتًا بعد نحو 49.7 يومًا. نمط “افحص الساعة، وتصرّف إن حان الوقت” هو طريقة فعل عدة أشياء معًا دون حجب."},"10":{"title":"إيقاع قوس قزح","say":"وقفة قصيرة قبل أن تبدأ <code>loop()</code> من جديد. ‏256 خطوة، كل منها 20 ms، تساوي نحو خمس ثوانٍ لدورة كاملة حول عجلة الألوان.","deep":"لا بأس بـ <code>delay()</code> قصيرة هنا لأن لا شيء آخر يحتاج انتباهًا. في الداخل تتيح <code>delay()</code> لـ FreeRTOS تشغيل مهام أخرى بدل الدوران في مكانها، فتوفّر قليلًا من الطاقة أيضًا.","quiz":{"question":"لو غيّرتها إلى <code>delay(5)</code>، ماذا سترى؟","options":["قوس قزح نفسه، أسرع أربع مرات","قوس قزح أخفت","LED يومض مضيئًا ومطفأً"],"why":"تستغرق كل خطوة الآن 5 ms بدل 20، فتستغرق الدورة الكاملة نحو 1.3 ثانية. يضبط السطوع <code>kBrightness</code> وليس التأخير."}}}},"kit/include/pins.h":{"stops":{"0":{"title":"ملف واحد لكل سلك","say":"تقرأ كل الدروس أرقام أطرافها من هنا، فتغيير سلك يعني تغيير رقم واحد. تحذّرك القائمة من الأطراف التي تستخدمها الشريحة أصلًا للإقلاع وUSB وذاكرة flash وPSRAM.","deep":"يمنع <code>#pragma once</code> لصق الملف مرتين إذا ضمّنته عدة ملفات."},"1":{"title":"أين يعيش LED قوس قزح","say":"<code>PIN_RGB</code> يساوي 48 في معظم اللوحات. إن لم يُظهر الدرس 01 أي لون، فقد تكون لوحتك إصدار v1.1 الذي يستخدم 38: غيّر الرقم هنا.","deep":"يضع الغلاف <code>#ifndef</code> ... <code>#endif</code> قيمة افتراضية فقط: ويتغلب عليها خيار بناء مثل <code>-DPIN_RGB=38</code> في <code>platformio.ini</code> دون تعديل هذا الملف."},"2":{"title":"أطراف للدروس القادمة","say":"الباقي هو الأزرار وLED والشاشة وقارئ RFID وقطع الصوت للدروس اللاحقة. يوضح كل تعليق أي ملصق على الوحدة يذهب إلى أي طرف في ESP32."}}}}}`),"02-led":JSON.parse(`{"bigPicture":"يقود هذا البرنامج LED على لوحة التجارب (breadboard) ويستمع إلى أوامر تكتبها في المراقب التسلسلي. تعمل <code>setup()</code> مرة واحدة لتسلّم الطرف إلى عتاد PWM وتبدأ تلاشيًا لطيفًا. ثم تعمل <code>loop()</code> إلى الأبد، وتنجز مهمتين سريعتين في كل دورة: قراءة أي حروف مكتوبة، وضبط سطوع LED للوضع الحالي، فلا يتوقف عن الحركة وهو يستمع.","files":{"labs/02-led/src/main.cpp":{"stops":{"0":{"title":"الدائرة والأوامر","say":"يعرض الرسم الصغير الدائرة: الطرف 4، عبر مقاومة، إلى الساق الطويلة لـ LED، ومن ساقه القصيرة إلى GND. تحته الفكرتان الجديدتان والأوامر التي يمكنك كتابتها.","deep":"تحدّ المقاومة من التيار: مع نحو 3.3 V من الطرف، ونحو 2 V عبر LED أحمر و220 Ω، يكون التيار نحو 5 mA، وهو آمن لـ LED وللطرف معًا."},"1":{"title":"أدوات، وإضافة منخفضة المستوى","say":"مثل الدرس 01، مع إضافة واحدة: يمنح <code>driver/gpio.h</code> وصولًا مباشرًا إلى إعدادات أطراف الشريحة، ونستخدمه كشبكة أمان في <code>setup()</code>.","deep":"يأتي <code>driver/gpio.h</code> من ESP-IDF، إطار Espressif الذي بُنيت عليه نواة Arduino، فيمكن لنوعي الاستدعاء أن يعيشا في برنامج واحد."},"2":{"title":"تزييف نصف السطوع","say":"لا يستطيع الطرف إلا أن يكون مشغّلًا تمامًا أو مطفأً تمامًا. يبدّله PWM 5000 مرة في الثانية؛ وحصة الوقت التي يقضيها مشغّلًا (duty) تحدد مدى سطوع LED. مع 8 بتات يمتد duty من 0 (مطفأ) إلى 255 (مشغّل دائمًا).","deep":"تولّد طرفية LEDC في S3 إشارة PWM بالعتاد، فيبقى المعالج حرًّا. يعمل عدّادها من ساعة APB بتردد 80 MHz: ‏5 kHz × 256 خطوة يحتاج مقسّمًا قيمته 62.5، وهو مدعوم.","quiz":{"question":"يحصل LED على duty قيمته 128 بتردد 5000 Hz. ماذا ترى؟","options":["وميض سريع مرئي","توهّج ثابت، أخفت من الكامل","لا شيء: نصف التشغيل يُعد إطفاءً"],"why":"5000 تبديلة في الثانية أسرع بكثير من أن تلحظها عيناك، فتحسبان متوسط الضوء توهجًا ثابتًا أخفت."}},"3":{"title":"ذاكرة LED","say":"تسرد <code>Mode</code> كل سلوك يمكن أن يتخذه LED. وتتذكر <code>state</code> السلوك الحالي، والسطوع لوضعي <i>on</i> و<i>blink</i>، وسرعة الوميض، ووقت بدء الوضع الحالي.","deep":"هذا هو قلب آلة الحالات: كل ما يحتاجه البرنامج ليقرر السطوع التالي يعيش في <code>struct</code> صغير واحد، والأوامر لا تغيّر إلا هذه الحقول.","quiz":{"question":"ترفع البرنامج إلى اللوحة ولا تكتب شيئًا. ماذا يفعل LED؟","options":["يبقى مطفأً","يتوهج بالكامل","يتلاشى صعودًا وهبوطًا"],"why":"يبدأ <code>mode</code> بالقيمة <code>Mode::Fade</code>، وتضبط <code>setup()</code> التلاشي مرة أخرى، فيتنفس LED حتى تكتب شيئًا."}},"4":{"title":"حوّل الوضع إلى كلمة","say":"تمنح كل وضع اسمًا قابلًا للطباعة، ليعرض المراقب <code>mode -> blink</code> بدل رقم مجرد.","deep":"لا يُبلَغ <code>return \\"?\\"</code> بعد <code>switch</code> اليوم أبدًا، لكنه يُرضي المترجم ويبقى آمنًا إن أضاف أحد وضعًا ونسي اسمه."},"5":{"title":"اجعل التلاشي يبدو متساويًا","say":"تلحظ عيناك التغيّرات في الضوء الخافت أكثر بكثير مما في الضوء الساطع. تربيع القيمة يُبقي LED خافتًا مدة أطول ويسرع في الطرف الساطع، فيبدو التلاشي سلسًا بدل أن يقفز إلى الساطع دفعة واحدة.","deep":"هذا منحنى غاما بقيمة 2: ‏<code>x * x / 255</code>. التوسيع إلى <code>uint16_t</code> أولًا مهم، لأن 255 × 255 = 65025 لا يتسع في 8 بتات."},"6":{"title":"بدّل الأوضاع وأعد ضبط الساعة","say":"يخزّن تغيير الوضع الوضع الجديد، ويسجّل وقت بدئه، ويكتب التغيير في المراقب.","deep":"تسجيل <code>modeStartedAt</code> يعني أن كل حركة تقيس الزمن من بدايتها، فيبدأ <i>sos</i> دائمًا بالنقطة الأولى."},"7":{"title":"ذكّرك بالأوامر","say":"يطبع قائمة الأوامر والإعدادات الحالية. يعمل عند بدء التشغيل وكلما كتبت <code>help</code>."},"8":{"title":"شيفرة مورس كسلسلة نصية","say":"يُخزَّن SOS كصف من الأصفار والآحاد: كل حرف شريحة زمنية 150 ms، والواحد للضوء والصفر للظلام. السلاسل القصيرة من الآحاد نقاط، والطويلة شرطات، والأصفار في النهاية هي الوقفة قبل التكرار.","deep":"للسلسلة 33 حرفًا، فيستغرق SOS كامل 33 × 150 ms، أي أقل من 5 ثوانٍ بقليل. تخزين النمط كبيانات بدل شيفرة يُبقي منطق الرسم صغيرًا جدًا."},"9":{"title":"وصفة السطوع","say":"بمعرفة المدة التي يعمل فيها الوضع الحالي، تجيب هذه الدالة عن سؤال واحد: كم يجب أن يكون سطوع LED الآن؟ الوضع <i>Off</i> هو 0، و<i>on</i> هو مستواك، و<i>blink</i> يتناوب بين المستوى و0.","deep":"في blink، يعدّ <code>elapsed / blinkMs</code> كم نصف دورة مضت؛ ويُبقي <code>% 2</code> فقط على كون العدد زوجيًا (مشغّل) أو فرديًا (مطفأ). لا مؤقتات ولا علَم تشغيل/إطفاء مخزَّن.","quiz":{"question":"تكتب <code>blink 100</code>. كم ومضة ترى في الثانية؟","options":["10","5","1"],"why":"100 ms مشغّل، ثم 100 ms مطفأ: ومضة كل 200 ms، أي خمس في الثانية."}},"10":{"title":"التنفس ومورس","say":"يرتفع <i>Fade</i> من الظلام إلى الساطع خلال ثانية، ثم ينزل خلال الثانية التالية، ويمرّر النتيجة عبر المنحنى الملائم للعين. ويحسب <i>SOS</i> أي شريحة من سلسلة مورس نحن فيها ويضيء LED إن كانت 1.","deep":"التلاشي موجة مثلثية بدورة 2 s. و<code>sizeof(kSos) - 1</code> هو طول السلسلة دون علامة النهاية المخفية <code>'\\\\0'</code>؛ و<code>%</code> تجعل النمط يتكرر إلى الأبد."},"11":{"title":"رتّب ما كتبته، ثم تصرّف","say":"يصل الأمر كسطر نص واحد. يقصّ المسافات الزائدة، ويحوّل الحروف إلى صغيرة، ويقسمه عند أول مسافة إلى أمر ورقم اختياري. الأوامر ذات الكلمة الواحدة تبدّل الوضع ببساطة.","deep":"<code>String</code> نوع النص القابل للنمو في Arduino. تعيد <code>indexOf(' ')</code> القيمة -1 عند عدم وجود مسافة، فيكون <code>arg</code> فارغًا حينئذ."},"12":{"title":"أوامر تأخذ رقمًا","say":"يقرأ <code>blink</code> و<code>level</code> الرقم بعد الأمر ويتحققان من معقوليته قبل استخدامه. أي شيء لا تتعرف عليه اللوحة يحصل على تحذير مهذب بدل مفاجأة.","deep":"تعيد <code>toInt()</code> القيمة 0 عندما لا يكون النص رقمًا، فيضبط <code>level abc</code> بهدوء القيمة 0 (مطفأ). التحقق من النطاقات مسبقًا يُبعد القيم السيئة عن <code>state</code>.","quiz":{"question":"LED يتلاشى وتكتب <code>blink 10</code>. ماذا يحدث؟","options":["يومض بسرعة كبيرة","يظهر تحذير ويواصل التلاشي","تُعاد ضبط اللوحة"],"why":"القيمة 10 أقل من الحد الأدنى 20 ms، فتسجّل الشيفرة تحذيرًا وتعود قبل استدعاء <code>setMode</code>. لا شيء يتغير."}},"13":{"title":"استمع دون انتظار","say":"تلتقط هذه الدالة أي حروف وصلت بالفعل، وتضيفها إلى مخزن صغير، وعندما ترى Enter تسلّم السطر كاملًا إلى <code>handleCommand</code>. وإن لم يصل شيء تعود فورًا، فيواصل LED الحركة وأنت تكتب.","deep":"لا تنتظر <code>Serial.available()</code> أبدًا. يرسل المراقب سطرًا جديدًا (line feed) في النهاية (<code>monitor_eol = LF</code>)؛ ويُقبل carriage return أيضًا. حد 32 حرفًا يمنع سطرًا خارجًا عن السيطرة من أكل الذاكرة."},"14":{"title":"سلّم الطرف إلى PWM","say":"تعمل مرة واحدة. تفتح المراقب التسلسلي، وتوصّل الطرف 4 بعتاد PWM، وتخفض قدرة الطرف كشبكة أمان، وتطفئ LED قوس قزح المتبقي من الدرس 01، وتبدأ التلاشي.","deep":"تختار <code>ledcAttach</code> قناة LEDC حرة للطرف. و<code>GPIO_DRIVE_CAP_0</code> أضعف قوة قيادة (نحو 5 mA)، وتحمي LED والطرف إن غابت المقاومة؛ ومع مقاومة مناسبة يمكنك إزالتها للحصول على سطوع كامل."},"15":{"title":"استمع، ثم أضئ","say":"كل 5 ms: افحص الحروف المكتوبة، واحسب السطوع للوضع الحالي، واكتبه في LED. ولأن أيًّا من الخطوتين لا تنتظر، فلا تجمّد الكتابة الحركة أبدًا.","deep":"<code>millis() - state.modeStartedAt</code> هو الزمن منذ بدء الوضع، وهذا كل ما تحتاجه <code>dutyFor</code>. تحدّث <code>ledcWrite</code> مسجّلًا فقط؛ ويُبقي عتاد LEDC إشارة PWM تعمل بين الاستدعاءات.","quiz":{"question":"في منتصف SOS تكتب <code>sos</code> مرة أخرى. ماذا يحدث؟","options":["لا شيء: هو في SOS بالفعل","يعيد النمط البدء من النقطة الأولى","ينطفئ"],"why":"تعيد <code>setMode</code> ضبط <code>modeStartedAt</code>، فيعود الزمن المنقضي إلى 0 ويبدأ النمط من جديد."}}}}}}`),"03-display":JSON.parse(`{"bigPicture":"يضيء هذا البرنامج الشاشة مقاس 1.9″. تعمل <code>setup()</code> مرة واحدة: تشغّل الإضاءة الخلفية، وتجهّز ناقل SPI، وتعرض أعمدة حمراء وخضراء وزرقاء لتتحقق من الألوان، ثم تحجز لوحة رسم بحجم صورة في PSRAM. ثم تعمل <code>loop()</code> إلى الأبد، فترسم موجة جيبية متحركة مع معدل الإطارات ومدة التشغيل على تلك اللوحة، وترسل كل صورة منتهية إلى الشاشة دفعة واحدة.","files":{"labs/03-display/src/main.cpp":{"stops":{"0":{"title":"التوصيل والخطة","say":"يسرد الرأس أي طرف في الشاشة يذهب إلى أي طرف في اللوحة، وما سترى (أعمدة ألوان، ثم موجة متحركة)، والفكرتين الجديدتين: ناقل SPI والمخزن المؤقت للإطار (frame buffer).","deep":"ST7789 هي شريحة التحكم في وحدة الشاشة؛ تحتفظ بالصورة في ذاكرتها وتجدد الزجاج بنفسها. ونحن نرسل لها بكسلات جديدة فقط."},"1":{"title":"مكتبات تعرف الشاشة","say":"تعرف <code>Adafruit_GFX</code> كيف ترسم الخطوط والمستطيلات والنص. وتعرف <code>Adafruit_ST7789</code> كيف تتحدث إلى هذه الشاشة. و<code>SPI.h</code> هو الناقل الذي تستخدمانه.","deep":"إصدارات المكتبات الدقيقة مثبّتة في <code>platformio.ini</code> تحت <code>lib_deps</code>، فيستخدم كل بناء الشيفرة نفسها."},"2":{"title":"حجم الشاشة وسرعة الناقل","say":"اللوحة 170 × 320 بكسل؛ ندير الشاشة جانبيًا فتصبح بعرض 320 وارتفاع 170. و<code>kSpiHz</code> هو سرعة سفر البتات في السلك: 40 مليونًا في الثانية.","deep":"الصورة الكاملة 320 × 170 × 16 بتًّا ≈ 870 ألف بت، فعند 40 MHz يستغرق إرسالها نحو 22 ms. والفاصلة العليا <code>'</code> في <code>40'000'000</code> مجرد فاصل أرقام لتسهيل القراءة.","quiz":{"question":"تخفض <code>kSpiHz</code> إلى 20 MHz. ما الذي يتغير على الشاشة؟","options":["تصبح الألوان أشحب","ينخفض رقم fps","تنكمش الصورة"],"why":"تستغرق كل صورة ضعف الوقت لتُرسل، فيصل عدد أقل من الإطارات إلى الشاشة كل ثانية. أما الصورة نفسها فمطابقة."}},"3":{"title":"الشاشة ولوحة الرسم","say":"<code>tft</code> هو الكائن الذي يتحدث إلى الشاشة الحقيقية. و<code>frame</code> سيشير إلى لوحة رسم: صورة غير مرئية في الذاكرة نرسم عليها كل إطار قبل عرضه. تبدأ بالقيمة <code>nullptr</code>، أي “لا شيء بعد”.","deep":"تحتاج لوحة الرسم إلى 320 × 170 × 2 بايت ≈ 106 KB. هذا كثير ليبقى براحة في الذاكرة RAM الداخلية لـ S3، فتذهب إلى PSRAM سعة 8 MB: تضع النواة الحجوزات الكبيرة هناك تلقائيًا."},"4":{"title":"ألوان في 16 بتًّا","say":"يتسع لون كل بكسل في 16 بتًّا: 5 للأحمر و6 للأخضر و5 للأزرق (RGB565). تحمل <code>pal</code> الألوان الستة لراسم الذبذبات الصغير لدينا، ولكل لون اسم يقول لماذا يُستخدم.","deep":"يحصل الأخضر على البت الإضافي لأن أعيننا أكثر حساسية له. تقلّص 16 بتًّا لكل بكسل البيانات المرسلة إلى النصف مقارنة بلون 24 بتًّا، على حساب تدرّج طفيف في التدرجات الناعمة."},"5":{"title":"امزج ألوان راسم الذبذبات","say":"تملأ اللوحة اللونية من مقادير سهلة 0-255 للأحمر والأخضر والأزرق: خلفية زرقاء داكنة تميل إلى الأسود، وشبكة باهتة، وخط أخضر مزرق، وأرقام كهرمانية، ولونا نص.","deep":"يُبقي <code>color565</code> على أعلى 5 و6 و5 بتات من كل قناة ويحزمها في عدد واحد من 16 بتًّا."},"6":{"title":"أحمر، أخضر، أزرق: اختبار سريع","say":"ترسم ثلاثة أعمدة وتسمّيها. إن كان العمود الأيسر أحمر والأوسط أخضر والأيمن أزرق، فالتوصيل وإعدادات الألوان صحيحة. يُرسم هذا مباشرة على الشاشة، دون لوحة الرسم.","deep":"<code>ST77XX_RED</code> وأخواتها قيم RGB565 جاهزة. الرسم المباشر مناسب لصورة ثابتة واحدة؛ أما في الحركة فسترى كل عمود يظهر.","quiz":{"question":"تظهر الأعمدة سماوية وأرجوانية وصفراء بدلًا من ذلك. ما السبب المرجّح؟","options":["سلك مفكوك","الألوان معكوسة","PSRAM مفقودة"],"why":"السماوي والأرجواني والأصفر أضداد الأحمر والأخضر والأزرق. كما يقول التعليق، يصلح الأمر <code>tft.invertDisplay(false)</code> بعد <code>tft.init()</code> المشكلة."}},"7":{"title":"ارسم الشبكة","say":"ترسم خطوطًا رأسية وأفقية باهتة عبر الجزء السفلي من لوحة الرسم، مثل شبكة شاشة راسم الذبذبات.","deep":"<code>drawFastVLine</code> و<code>drawFastHLine</code> أرخص من <code>drawLine</code> العامة لأنهما لا تحتاجان إلا إلى ملء سلسلة مستقيمة من البكسلات."},"8":{"title":"امسح لوحة الرسم، واكتب الترويسة","say":"يبدأ كل إطار بطلاء لوحة الرسم كلها بلون الخلفية. ثم يكتب العنوان الكبير “hello, bench” وفي أعلى اليمين اسم اللوحة ومعدل الإطارات الحالي.","deep":"<code>g</code> هي لوحة الرسم الممرَّرة بالمرجع (<code>&amp;</code>)، فنرسم على اللوحة الحقيقية دون نسخ 106 KB. تضع <code>setCursor</code> النص؛ وتكبّر <code>setTextSize</code> الخط المدمج."},"9":{"title":"الموجة المسافرة","say":"لكل عمود من البكسلات تحسب ارتفاع موجة جيبية وتصله بالعمود السابق بخط قصير. يعتمد موضع الموجة على الزمن، فتكون قد تحركت قليلًا في كل إطار: وهذه هي الحركة التي تراها.","deep":"طول الموجة الرئيسية نحو 140 px وتنجرف بنحو 67 px في الثانية. وتجعل موجة جيبية ثانية بطيئة ارتفاعها “يتنفس” بين 70% و100%، وتضيف موجة صغيرة سريعة تموّجًا. خط المنتصف عند y = 102."},"10":{"title":"ساعة في الزاوية","say":"تحوّل المللي ثانية منذ بدء التشغيل إلى ساعات ودقائق وثوانٍ وتطبعها بالكهرماني في أسفل اليمين.","deep":"<code>s / 60 % 60</code> هو إجمالي الدقائق مطروحًا منه الساعات الكاملة. تملأ <code>%02lu</code> كل رقم إلى خانتين بصفر في البداية.","quiz":{"question":"تعمل اللوحة منذ 3725 ثانية. ماذا تعرض الساعة؟","options":["00:62:05","01:02:05","01:00:25"],"why":"3725 s هي ساعة واحدة (3600 s) زائد 125 s، و125 s هي دقيقتان وخمس ثوانٍ."}},"11":{"title":"الإضاءة الخلفية أولًا","say":"تعمل مرة واحدة. بعد فتح المراقب التسلسلي تشغّل الإضاءة الخلفية قبل أي شيء آخر. فإذا توهجت الشاشة وبقيت فارغة، فأنت تعلم أن الطاقة والإضاءة الخلفية سليمتان وأن المشكلة في أسلاك البيانات.","deep":"الإضاءة الخلفية مجموعة LED خلف اللوحة؛ ويشغّلها الطرف BLK فقط. ويمكن أن يستقبل PWM أيضًا، كما في الدرس 02، لتخفيت الشاشة."},"12":{"title":"ابدأ الناقل، وأيقظ الشاشة","say":"تبدأ SPI على أطرافنا، وتوقظ الشاشة، وتضبط السرعة، وتديرها جانبيًا وتمزج اللوحة اللونية. يؤكد سطر السجل الحجم والسرعة، فيجب أن يقول المراقب 320x170 عند 40 MHz.","deep":"لا ترسل الشاشة بيانات عائدة أبدًا، لذا فإن MISO هو <code>-1</code>. كائن <code>SPI</code> الافتراضي في S3 هو طرفية SPI2 ‏(FSPI). تبدّل <code>setRotation(1)</code> العرض والارتفاع، ولهذا يطبع السجل 320x170."},"13":{"title":"اعرض الأعمدة، ثم أنشئ لوحة الرسم","say":"تعرض أعمدة الألوان لمدة ثانيتين ونصف، ثم تطلب لوحة الرسم بحجم 106 KB. إن فشل ذلك، تسجّل خطأ وتستسلم، فتعرف أن عليك فحص إعداد PSRAM.","deep":"ينجح <code>new GFXcanvas16</code> حتى لو تعذّر حجز مخزن البكسلات، لذا تفحص الشيفرة الكائن و<code>getBuffer()</code> معًا.","quiz":{"question":"لو أُطفئت PSRAM وتعذّر إنشاء لوحة الرسم، ماذا ستعرض الشاشة؟","options":["شاشة سوداء","أعمدة الألوان، مجمّدة","موجة متذبذبة"],"why":"تُرسم الأعمدة قبل طلب لوحة الرسم، ثم تنتظر <code>loop()</code> فقط، فلا يرسم شيء فوقها أبدًا."}},"14":{"title":"قِس معدل الإطارات","say":"تعمل إلى الأبد. إن لم توجد لوحة رسم فإنها تنتظر فقط. وإلا تقيس الزمن منذ الإطار الأخير وتحوّله إلى إطارات في الثانية، مع تنعيم حتى لا يتذبذب الرقم على الشاشة.","deep":"يُبقي التنعيم 90% من القيمة القديمة ويضيف 10% من الجديدة (متوسط متحرك أسّي). تحتفظ المتغيرات <code>static</code> بقيمها بين الدورات."},"15":{"title":"ارسم في السر، واعرض دفعة واحدة","say":"تُرسم الصورة كلها أولًا على لوحة الرسم، ثم ترسلها <code>drawRGBBitmap</code> إلى الشاشة في دفعة طويلة واحدة. وكل خمس ثوانٍ يُطبع معدل الإطارات في المراقب أيضًا.","deep":"الرسم مباشرة على الشاشة سيُظهر كل خطوة (الخلفية والشبكة والموجة) أثناء حدوثها، فيحدث وميض. أما مع المخزن المؤقت للإطار فلا تتلقى الشاشة إلا صورًا منتهية.","quiz":{"question":"لماذا تتحرك الموجة دون وميض؟","options":["الشاشة تُحدَّث بسرعة كبيرة","يُنهى كل إطار في الذاكرة قبل أن يُرسل","ناقل SPI بسرعة 40 MHz"],"why":"تستقبل لوحة الرسم في PSRAM كل الخطوات نصف المنتهية؛ ولا تحصل الشاشة إلا على الصورة النهائية."}}}}}}`)};export{e as default};
